import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Main {
    static final long MOD = 998244353L;
    static long[] fact = new long[1];
    static long[] invFact = new long[1];
    static {
        fact[0] = 1;
        invFact[0] = 1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long k = Long.parseLong(st.nextToken());
        PrintWriter out = new PrintWriter(System.out);
        if (k == 0) {
            out.println(fact(n));
            out.close();
            return;
        }
        if (k > n - 1) {
            out.println(0);
            out.close();
            return;
        }
        int c = (int)(n - k);
        long answer = 0;
        int i = 1;
        while (i <= c) {
            long term = mult(parity(c - i), ncr(c, i), pow(i, n));
            answer = add(answer, term);
            i++;
        }
        answer = mult(answer, 2, ncr(n, c));
        out.println(answer);
        out.close();
    }

    static long fact(int n) {
        if (n >= fact.length) {
            int old = fact.length;
            long[] newFact = new long[n + 1];
            long[] newInv = new long[n + 1];
            System.arraycopy(fact, 0, newFact, 0, old);
            System.arraycopy(invFact, 0, newInv, 0, old);
            for (int j = old; j <= n; j++) {
                newFact[j] = newFact[j - 1] * j % MOD;
            }
            newInv[n] = pow(newFact[n], (int)(MOD - 2));
            for (int j = n - 1; j >= old; j--) {
                newInv[j] = newInv[j + 1] * (j + 1) % MOD;
            }
            fact = newFact;
            invFact = newInv;
        }
        return fact[n];
    }

    static long invFact(int n) {
        fact(n);
        return invFact[n];
    }

    static long ncr(int n, int r) {
        if (r < 0 || r > n) return 0;
        return mult(fact(n), invFact(r), invFact(n - r));
    }

    static long parity(long k) {
        return (k & 1) == 0 ? 1 : MOD - 1;
    }

    static long add(long a, long b) {
        long v = a + b;
        return v >= MOD ? v - MOD : v;
    }

    static long mult(long... x) {
        long r = 1;
        for (long v : x) r = r * v % MOD;
        return r;
    }

    static long pow(long x, int e) {
        if (e < 0) {
            x = inv(x);
            e = -e;
        }
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * x % MOD;
            x = x * x % MOD;
            e >>= 1;
        }
        return res;
    }

    static long inv(long x) {
        return pow(x, (int)(MOD - 2));
    }
}
